package site.kael.conversationcompiler.manager;
import org.junit.jupiter.api.Test; import site.kael.conversationcompiler.domain.*; import site.kael.conversationcompiler.domain.compiler.*; import site.kael.conversationcompiler.domain.settings.*; import site.kael.conversationcompiler.manager.compiler.ConversationCompileScheduler; import site.kael.conversationcompiler.repository.*; import site.kael.conversationcompiler.repository.compiler.*; import site.kael.conversationcompiler.repository.settings.*; import java.util.*; import static org.mockito.Mockito.*;
class ConversationCompileSchedulerTest { @Test void createsPendingRunForIdleUncompiledConversation(){var c=mock(ConversationRepository.class);var r=mock(CompileRunRepository.class);var s=mock(KnowledgeSettingsRepository.class);var x=new ConversationSummary("s","agent-trace","t","","","",1d,System.currentTimeMillis()/1000d-3600,2,5,2,"active",null,"","");when(s.find()).thenReturn(Optional.of(new KnowledgeCompileSettings("p","P","m",30,"",true,"")));when(c.findIdleCandidates(anyDouble(),anyInt())).thenReturn(List.of(x));when(r.hasActiveRun("s")).thenReturn(false);new ConversationCompileScheduler(c,r,s).scanIdleConversations();verify(r).createPending("s",3,5,0,0,3,CompileTriggerType.scheduler);}}
